    '.dm-count.full{background:var(--ok-bg,#E7F4EC);color:var(--ok-ink,#1E6B3E)}',
    '.dm-dots{display:flex;gap:6px}.dm-dots i{width:7px;height:7px;border-radius:4px;background:var(--line,#DDE0E6);transition:background .3s}.dm-dots i.on{background:var(--brand,#1D3C9E)}',
    '.dm-fade{opacity:0;transform:translateY(6px);transition:opacity .45s,transform .45s}.dm-fade.in{opacity:1;transform:none}',
