    '.nl-seg.in{transform:scaleX(1)}',
    '.nl-lab{position:absolute;top:6px;font-size:12px;font-weight:600;text-align:center;transform:translateX(-50%);white-space:nowrap}',
    '.nl-tick{position:absolute;top:88px;font-size:12px;color:var(--muted,#5F6672);transform:translateX(-50%);font-family:var(--mono,monospace)}',
    '.nl-dot{position:absolute;top:0;width:30px;height:30px;margin-left:-15px;border-radius:15px;background:var(--brand,#1D3C9E);color:#fff;font-size:11px;font-weight:600;display:flex;align-items:center;justify-content:center;opacity:0;transform:translateY(-20px);transition:all .5s cubic-bezier(.3,1.4,.6,1)}',
    '.nl-dot.in{opacity:1;transform:translateY(32px)}',
    '.nl-dot.alt{background:var(--avg,#E8A33D);color:#15171C}',
    '.nl-chip{position:absolute;top:118px;font-size:12px;padding:3px 8px;border-radius:10px;border:1px dashed #C9372C;color:#8F1D12;background:#FDECEA}',
    /* BVA zoom lines */
    '.bz{display:flex;gap:28px;flex-wrap:wrap}',
    '.bz-box{flex:1;min-width:260px}',
    '.bz-cap{font-size:12px;color:var(--muted,#5F6672);margin-bottom:6px}',
    '.bz-row{display:grid;grid-template-columns:repeat(8,1fr);gap:4px}',
    '.bz-cell{position:relative;text-align:center;font-family:var(--mono,monospace);font-size:13px;padding:22px 0 8px;border-radius:6px;transition:all .4s}',
    '.bz-cell.v{background:#E7F4EC}.bz-cell.x{background:#FDECEA}',
    '.bz-cell.edge{box-shadow:inset 0 0 0 2px var(--ink,#15171C);font-weight:700}',
    '.bz-cell b{position:absolute;top:4px;left:50%;width:14px;height:14px;margin-left:-7px;border-radius:7px;transform:scale(0);transition:transform .4s cubic-bezier(.3,1.6,.6,1)}',
    '.bz-cell.t2 b{transform:scale(1);background:var(--brand,#1D3C9E)}',
    '.bz-cell.t3 b{transform:scale(1);background:var(--avg,#E8A33D)}',
