    /* decision table */
    '.dt{border-collapse:collapse;font-size:14px;min-width:520px}',
    '.dt th,.dt td{border:1px solid var(--line,#DDE0E6);padding:8px 12px;text-align:center;transition:background .35s}',
    '.dt th{background:#F7F8FA;text-align:left;font-weight:600}',
    '.dt td.cell span{display:inline-block;transform:scale(0);transition:transform .35s cubic-bezier(.3,1.6,.6,1)}',
    '.dt td.cell.in span{transform:scale(1)}',
    '.dt td.T span{color:var(--ok-ink,#1E6B3E);font-weight:700}.dt td.F span{color:var(--bad-ink,#8F1D12);font-weight:700}',
    '.dt td.X span{color:var(--brand,#1D3C9E);font-weight:700}',
    '.dt .col-on{background:var(--brand-bg,#E8EDFB)}',
    '.dt .col-done{background:#F2FAF5}',
    '.dt tr.sep td,.dt tr.sep th{border-top:3px solid var(--ink2,#2B2F38)}',
    '.dt .tdata{font-size:12px;color:var(--ink2,#2B2F38);line-height:1.35}',
    /* code + cfg */
    '.cv{display:flex;gap:22px;flex-wrap:wrap;align-items:flex-start}',
    '.code{font-family:var(--mono,monospace);font-size:14px;background:#F7F8FA;border:1px solid var(--line,#DDE0E6);border-radius:8px;padding:8px 0;min-width:300px;flex:1}',
    '.code div{padding:3px 14px 3px 10px;white-space:pre;transition:background .35s,box-shadow .35s;border-left:4px solid transparent}',
    '.code div i{display:inline-block;width:26px;color:#9AA0AA;font-style:normal}',
    '.code div.hit{background:#E7F4EC;border-left-color:var(--strong,#1E7A46)}',
    '.code div.now{background:#FFF1C2;border-left-color:var(--avg,#E8A33D)}',
    '.code div.miss{background:#FDECEA;border-left-color:var(--weak,#C9372C)}',
    '.cfg{flex:0 0 260px}',
    '.cfg text{font-family:var(--sans,sans-serif);font-size:12px}',
    '.cfg .e{stroke:#B8BEC9;stroke-width:2.5;fill:none;transition:stroke .4s,stroke-width .4s}',
    '.cfg .e.hit{stroke:var(--strong,#1E7A46);stroke-width:4}',
    '.cfg .n{fill:#fff;stroke:#5F6672;stroke-width:2;transition:fill .4s}',
    '.cfg .n.hit{fill:#E7F4EC;stroke:var(--strong,#1E7A46)}',
    '.cfg .lab{fill:var(--muted,#5F6672)}',
    /* state machine */
    '.sm{min-width:600px}',
    '.sm .st{fill:#fff;stroke:#5F6672;stroke-width:2;transition:fill .4s,stroke .4s}',
    '.sm .st.hit{fill:#E7F4EC;stroke:var(--strong,#1E7A46)}',
    '.sm .tr{stroke:#B8BEC9;stroke-width:2.5;fill:none;transition:stroke .4s}',
    '.sm .tr.hit{stroke:var(--strong,#1E7A46)}',
    '.sm .tr.now{stroke:var(--avg,#E8A33D);stroke-width:4}',
    '.sm text{font-family:var(--sans,sans-serif);font-size:12.5px}',
