    '.sm .tok{transition:transform .9s cubic-bezier(.5,0,.3,1)}',
    '.sm-tests{display:flex;gap:8px;flex-wrap:wrap;font-size:12.5px}',
    '.sm-tests span{padding:3px 9px;border-radius:12px;background:#F2F3F5;color:var(--muted,#5F6672);transition:all .3s}',
    '.sm-tests span.on{background:var(--brand-bg,#E8EDFB);color:var(--brand,#1D3C9E);font-weight:600}',
