    '.dmc-pin.m span{border-color:var(--brand,#1D3C9E);background:var(--brand,#1D3C9E);color:#fff}.dmc-pin.m i{background:var(--brand,#1D3C9E)}',
    '.dmc-mk{position:absolute;width:0;opacity:0;transition:left .45s,opacity .45s}.dmc-mk.in{opacity:1}',
    '.dmc-mk span{position:absolute;left:0;transform:translateX(-50%);white-space:nowrap;font-size:12px;font-weight:700;padding:2px 8px;border-radius:10px;font-family:var(--mono,monospace)}',
    '.dmc-mk i{position:absolute;left:-1px;width:2px}',
    '.dmc-mk.e{z-index:2}.dmc-mk.e span{background:var(--good,#2952CC);color:#fff}.dmc-mk.e i{background:var(--good,#2952CC)}',
    '.dmc-mk.avg span{background:#FDECEA;color:#8F1D12;border:1.5px dashed var(--weak,#C9372C)}.dmc-mk.avg i{border-left:2px dashed var(--weak,#C9372C);width:0}',
    '.dmc-wrow{display:flex;gap:5px;align-items:center;flex-wrap:wrap;margin-top:8px;font-size:13px}',
    '.dmc-wrow .lab{width:118px;font-size:12px;color:var(--muted,#5F6672)}',
