    '.dmc-blk.in{opacity:1;transform:none}',
    '.dmc-blk.m{background:var(--brand-bg,#E8EDFB);border-color:var(--brand,#1D3C9E);color:var(--brand,#1D3C9E)}',
    '.dmc-blk.x{background:#FDECEA;border-color:var(--weak,#C9372C);color:#8F1D12}',
